import {holes,forecast,clock} from './pace.js';
import {pinehurstHoles,videoSource,positionOnHole,courseSource} from './pinehurst.js';
const safe=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function journeyRows(group,groups){const f=forecast(group,groups);return holes.map((target,i)=>{const h=i+1,a=f.arrivals.find(x=>x.hole===h);const passed=h<group.hole,current=h===group.hole;return {hole:h,target,passed,current,eta:passed?'Played':current?'Playing now':clock(a.at),etaLabel:passed?'ROUND PROGRESS':current?'ON THIS HOLE':'ESTIMATED ARRIVAL',exit:passed?null:clock(f.arrivals.find(x=>x.hole===h+1)?.at??f.finish),occupancy:groups.filter(g=>g.hole===h).length};});}
function paceState(g,groups){const delay=forecast(g,groups).delay;return {delay,cls:delay>10?'late':delay>5?'watch':'on',text:delay>5?`${delay}m behind`:'On pace'};}
export function holeTraffic(h,groups,selected){const present=groups.filter(g=>g.hole===h),target=holes[h-1];return `<div class="hole-position"><div class="position-label"><span>GROUP POSITIONS</span><small>SIMULATED · NOT GPS</small><button class="hole-traffic-link" data-hole="${h}" aria-label="View hole ${h} traffic">↗</button></div><div class="position-fairway"><span class="position-tee">TEE</span><svg viewBox="0 0 360 85" aria-hidden="true"><path d="M15 52 Q95 67 150 44 T345 30" stroke="#e1d7b8" stroke-width="44" fill="none" stroke-linecap="round"/><path d="M15 52 Q95 67 150 44 T345 30" stroke="#9bb47d" stroke-width="28" fill="none" stroke-linecap="round"/><path d="M15 52 Q95 67 150 44 T345 30" stroke="#cad6ab" stroke-width="1" fill="none" stroke-dasharray="3 5"/><ellipse cx="335" cy="32" rx="22" ry="19" fill="#c1d29d"/><path d="M335 35v-24l12 4 -12 5" stroke="#3d5c37" fill="#3d5c37"/></svg>${present.map((g,i)=>{const p=positionOnHole(g,target),s=paceState(g,groups);return `<button class="golf-group-pin ${s.cls} ${g.id===selected?'selected':''}" data-group="${g.id}" style="left:${8+p*84}%;top:${39+(i%3)*12}%" aria-label="${safe(g.name)}, ${Math.round(p*100)} percent through hole, simulated, ${s.text}"><span>${String(g.id).padStart(2,'0')}</span><i>${Array.from({length:g.players},()=>'<b></b>').join('')}</i></button>`;}).join('')}<span class="position-green">GREEN</span></div>${present.length?`<div class="position-groups">${present.map(g=>{const s=paceState(g,groups);return `<button data-group="${g.id}" class="position-row"><span class="group-position-id ${s.cls}">${String(g.id).padStart(2,'0')}</span><span><strong>${safe(g.name)}${g.id===selected?' <small>YOUR GROUP</small>':''}</strong><small>${g.players} players · ${g.inHole} min on hole</small></span><em class="${s.cls}">${s.text}</em><span>↗</span></button>`;}).join('')}</div>`:'<p class="no-groups">No groups on this hole in the simulation.</p>'}</div>`;}
export function flightPosition(progress,holeProgress,lane=0){
 // Illustrative screen projection, not a georeferenced track or a measured GPS position.
 const distance=progress-holeProgress;
 return {x:50+lane*13+Math.sin(holeProgress*Math.PI)*5,y:Math.max(24,Math.min(69,49-distance*55))};
}
export function scrollFlight(scroll,top,height,viewport,count=18){
 const distance=Math.max(1,height-viewport),normalized=Math.max(0,Math.min(1,(scroll-top)/distance));
 const position=normalized*count,index=Math.min(count-1,Math.floor(position));
 return {index,progress:Math.min(1,position-index),total:normalized};
}
function flightPace(g,groups){const p=paceState(g,groups);return `<span class="flight-pace ${p.cls}">${p.text}</span>`;}
function flightPanel(r,h,group,groups){const here=groups.filter(g=>g.hole===r.hole);return `<section class="flight-panel" data-flight-panel="${r.hole}" ${r.hole===1?'':'hidden'}><div class="flight-hole-info"><div class="flight-hole-number">${String(r.hole).padStart(2,'0')}<span>/ 18</span></div><div class="flight-hole-title"><div class="flight-label">${r.hole<10?'THE FRONT NINE':'THE BACK NINE'} <i>·</i> PAR ${h.par} <i>·</i> ${h.yards} YDS</div><h2 id="hole-title-${r.hole}">${h.title}</h2><p>Pinehurst No. 2</p></div></div><div class="flight-stats chapter-eta"><div><span>${r.etaLabel}</span><strong>${r.eta}</strong></div><div><span>HOLE TARGET</span><strong>${r.target}<small> min</small></strong></div><div><span>${r.passed?'ROUND STATUS':'EST. CLEAR HOLE'}</span><strong>${r.passed?'Played':r.exit}</strong></div></div><div class="flight-on-course"><div class="flight-on-course-title"><span>ON THIS FAIRWAY <b>${here.length}</b></span><button data-hole="${r.hole}">Details ↗</button></div>${here.map(g=>`<button class="flight-group-row" data-group="${g.id}"><span class="flight-id ${paceState(g,groups).cls}">${String(g.id).padStart(2,'0')}</span><span><strong>${safe(g.name)}</strong><small>${g.players} golfers · ${g.inHole} min on hole${g.id===group.id?' · Following':''}</small></span>${flightPace(g,groups)}<span>↗</span></button>`).join('')||'<p class="flight-clear">This fairway is clear in the simulation.</p>'}<span class="flight-position-note">Simulated positions · not live GPS</span></div></section>`;}
export function journeyMarkup(group,groups){const rows=journeyRows(group,groups),f=forecast(group,groups);return `<div class="flight-scroll" id="flight-scroll"><div class="flight-stage"><div class="flight-cinema" aria-label="Scroll-controlled drone flight over Pinehurst No. 2"><img id="flight-poster" src="assets/pinehurst/flight-01.jpg" alt="Drone view of Pinehurst No. 2’s opening hole" fetchpriority="high"><video class="flight-video" id="flight-video-a" muted playsinline preload="auto" disablepictureinpicture aria-label="Pinehurst No. 2 scroll-controlled drone footage"></video><video class="flight-video" id="flight-video-b" muted playsinline preload="none" disablepictureinpicture aria-hidden="true"></video></div><div class="flight-vignette"></div><div class="flight-topbar"><button class="flight-brand" data-view="overview" aria-label="Open course dashboard"><span>⚑</span> fairway<span>flow</span></button><div class="flight-course"><h1>Pinehurst No. 2</h1><span>THE COURSE, IN MOTION</span></div><div class="flight-top-actions"><span class="flight-demo"><i></i>DEMO</span><button data-view="overview" class="flight-dashboard">Dashboard ↗</button></div></div><div class="flight-round-bar"><div><label for="journey-group">FOLLOWING</label><select id="journey-group">${groups.map(g=>`<option value="${g.id}" ${g.id===group.id?'selected':''}>${safe(g.name)}</option>`).join('')}</select></div><span>EST. ROUND FINISH <strong>${clock(f.finish)}</strong></span><button data-jump-hole="${Math.min(18,group.hole)}">Find my group ↗</button></div><div id="flight-loading" class="flight-loading" role="status">Preparing the fairway…</div><div class="flight-camera-tag"><span>◉</span> SCROLL-CONTROLLED FLIGHT <small id="flight-motion-hint">Scroll down to fly · scroll up to reverse</small></div><div class="flight-pins" aria-label="Simulated golfer positions">${rows.map(r=>`<div data-flight-pins="${r.hole}" ${r.hole===1?'':'hidden'}>${groups.filter(g=>g.hole===r.hole).map((g,i)=>`<button class="flight-world-pin ${paceState(g,groups).cls}" data-group="${g.id}" data-pin-progress="${positionOnHole(g,r.target)}" data-pin-lane="${i%3-1}" aria-label="${safe(g.name)}, ${g.players} golfers, simulated position"><span class="flight-pin-label"><strong>${safe(g.name)}</strong><small>${g.players} golfers <i>·</i> ${paceState(g,groups).text}</small></span><span class="flight-pin-stem"></span><span class="flight-golfers">${Array.from({length:g.players},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</span><span class="flight-pin-ring"></span></button>`).join('')}</div>`).join('')}</div><div class="flight-hud">${rows.map((r,i)=>flightPanel(r,pinehurstHoles[i],group,groups)).join('')}</div><div class="flight-bottom"><div class="flight-timeline"><span>01</span><div class="flight-track"><div id="flight-progress"></div>${rows.map(r=>`<button data-jump-hole="${r.hole}" style="left:${(r.hole-1)/18*100}%" aria-label="Fly to hole ${r.hole}" ${r.hole===1?'aria-current="step"':''}></button>`).join('')}</div><span>18</span></div><div class="flight-toolbar"><div class="flight-hole-nav"><button data-prev-hole aria-label="Previous hole">←</button><label for="hole-jump">HOLE</label><select id="hole-jump">${rows.map(r=>`<option value="${r.hole}">${String(r.hole).padStart(2,'0')}</option>`).join('')}</select><button data-next-hole aria-label="Next hole">→</button><button id="flight-motion-toggle" aria-pressed="false">Motion on</button></div><span class="flight-scroll-prompt">SCROLL TO EXPLORE <span>↓</span></span><button class="flight-advance" data-flight-advance>Advance demo 5 min ↻</button></div><div class="flight-credits"><a href="${videoSource}" target="_blank" rel="noopener">Footage: Golf Digest ↗</a><span>Independent Pinehurst concept · simulated golfers & ETAs</span><a href="${courseSource}" target="_blank" rel="noopener">Course details ↗</a></div></div></div><div class="flight-chapters">${rows.map(r=>`<article id="journey-hole-${r.hole}" class="flight-chapter" data-chapter="${r.hole}" tabindex="-1" aria-label="Hole ${r.hole}: ${r.etaLabel.toLowerCase()} ${r.eta}, target ${r.target} minutes"><span class="flight-sr">Hole ${r.hole}. ${r.etaLabel}: ${r.eta}. Target ${r.target} minutes.</span></article>`).join('')}</div></div>`;}
export function mountJourney(root){
 const runway=root.querySelector('.flight-scroll');if(!runway)return ()=>{};
 const chapters=[...root.querySelectorAll('[data-chapter]')],reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const slots=[root.querySelector('#flight-video-a'),root.querySelector('#flight-video-b')];
 const loading=root.querySelector('#flight-loading'),poster=root.querySelector('#flight-poster');
 let disposed=false,raf=0,active=-1,visibleSlot=null,requestedIndex=0,smoothPosition=0,targetPosition=0,motion=!reduced.matches,lastScroll=window.scrollY;
 const state=slots.map(video=>({video,index:-1,wanted:0,busy:false,ready:false}));
 function setStatus(text){loading.textContent=text;loading.hidden=!text;}
 function reveal(slot){if(disposed||slot.index!==requestedIndex||slot.video.readyState<2)return;slots.forEach(v=>v.classList.toggle('is-visible',v===slot.video));visibleSlot=slot;setStatus('');}
 function seek(slot){if(disposed||!slot.ready||slot.busy)return;const max=Math.max(0,slot.video.duration-.06),target=Math.max(0,Math.min(max,slot.wanted));if(Math.abs(slot.video.currentTime-target)<1/30){reveal(slot);return;}slot.busy=true;slot.video.currentTime=target;}
 state.forEach(slot=>{
  slot.video.addEventListener('loadedmetadata',()=>{slot.ready=true;seek(slot);});
  slot.video.addEventListener('loadeddata',()=>{if(slot.video.currentTime<.05)reveal(slot);});
  slot.video.addEventListener('seeked',()=>{slot.busy=false;reveal(slot);seek(slot);});
  slot.video.addEventListener('error',()=>{if(slot.index===requestedIndex){setStatus('Flight could not load. Showing this hole’s still preview.');slots.forEach(v=>v.classList.remove('is-visible'));visibleSlot=null;}});
 });
 function source(slot,index,wanted){slot.ready=false;slot.busy=false;slot.index=index;slot.wanted=wanted;slot.video.src=`assets/pinehurst/flight-${String(index+1).padStart(2,'0')}.mp4`;slot.video.load();}
 function requestFrame(index,progress){requestedIndex=index;let slot=state.find(s=>s.index===index);
  const wanted=motion?progress*7.94:0;
  if(!slot){slot=state.find(s=>s!==visibleSlot)||state[0];source(slot,index,wanted);setStatus('Flying to the next fairway…');}
  else {slot.wanted=wanted;seek(slot);}
  // Prepare the next hole in the spare element; keep only two decoders in memory.
  if(slot===visibleSlot&&slot.ready&&index<17){const spare=state.find(s=>s!==slot);if(spare.index!==index+1)source(spare,index+1,0);}
 }
 function update(){raf=0;if(disposed)return;
  const rect=runway.getBoundingClientRect(),scroll=window.scrollY,top=scroll+rect.top;
  const mapped=scrollFlight(scroll,top,runway.offsetHeight,innerHeight);targetPosition=mapped.index+mapped.progress;
  if(!motion||Math.abs(scroll-lastScroll)>innerHeight*2)smoothPosition=targetPosition;else smoothPosition+=(targetPosition-smoothPosition)*.22;
  if(Math.abs(targetPosition-smoothPosition)<.001)smoothPosition=targetPosition;
  lastScroll=scroll;
  const index=Math.max(0,Math.min(17,Math.floor(smoothPosition))),progress=Math.max(0,Math.min(1,smoothPosition-index));
  if(index!==active){active=index;const h=pinehurstHoles[index];root.querySelectorAll('[data-flight-panel]').forEach(el=>el.hidden=+el.dataset.flightPanel!==index+1);root.querySelectorAll('[data-flight-pins]').forEach(el=>el.hidden=+el.dataset.flightPins!==index+1);root.querySelector('#hole-jump').value=index+1;poster.src=`assets/pinehurst/flight-${String(index+1).padStart(2,'0')}.jpg`;poster.alt=`Drone view of Pinehurst No. 2 hole ${index+1}`;root.querySelector('[data-prev-hole]').disabled=index===0;root.querySelector('[data-next-hole]').disabled=index===17;root.querySelectorAll('.flight-track button').forEach(el=>{if(+el.dataset.jumpHole===index+1)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});}
  root.querySelector('#flight-progress').style.width=`${mapped.total*100}%`;
  root.querySelectorAll(`[data-flight-pins="${index+1}"] [data-pin-progress]`).forEach(pin=>{const p=flightPosition(+pin.dataset.pinProgress,motion?progress:.5,+pin.dataset.pinLane);pin.style.left=`${p.x}%`;pin.style.top=`${p.y}%`;});
  requestFrame(index,progress);
  if(Math.abs(targetPosition-smoothPosition)>.001)schedule();
 }
 function schedule(){if(!raf)raf=requestAnimationFrame(update);}
 function jump(h){const scroll=window.scrollY,rect=runway.getBoundingClientRect(),top=scroll+rect.top,distance=runway.offsetHeight-innerHeight;window.scrollTo({top:top+(h-1)/18*distance+1,behavior:motion?'smooth':'instant'});}
 function click(e){const button=e.target.closest('button');if(!button)return;if(button.dataset.jumpHole)jump(+button.dataset.jumpHole);if(button.hasAttribute('data-prev-hole'))jump(Math.max(1,active));if(button.hasAttribute('data-next-hole'))jump(Math.min(18,active+2));if(button.id==='flight-motion-toggle'){motion=!motion;setMotionLabel();schedule();}}
 function change(e){if(e.target.id==='hole-jump')jump(+e.target.value);}
 function setMotionLabel(){const button=root.querySelector('#flight-motion-toggle');button.textContent=motion?'Motion on':'Still mode';button.setAttribute('aria-pressed',String(!motion));root.querySelector('#flight-motion-hint').textContent=motion?'Scroll down to fly · scroll up to reverse':'Still mode · scroll between holes';}
 function preference(){motion=!reduced.matches;setMotionLabel();schedule();}
 root.addEventListener('click',click);root.addEventListener('change',change);window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);reduced.addEventListener('change',preference);setMotionLabel();update();
 return ()=>{disposed=true;cancelAnimationFrame(raf);root.removeEventListener('click',click);root.removeEventListener('change',change);window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);reduced.removeEventListener('change',preference);slots.forEach(v=>{v.removeAttribute('src');v.load();});};
}
